import { parsePythonInt, isNegativeIntegerToken } from './pythonInt.mjs'
import { basename } from '../utils/path.mjs'

const KNOWN_OPTIONS = new Set(['-h', '--help', '--a', '--b'])

function getProgramName(scriptPath) {
  const programName = basename(scriptPath)
  return programName || 'test4.mjs'
}

export function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B`
}

function buildParserError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}\n`
}

function isMissingOptionArgument(token) {
  if (token === undefined) {
    return true
  }

  if (KNOWN_OPTIONS.has(token) || token.startsWith('--')) {
    return true
  }

  return token.startsWith('-') && !isNegativeIntegerToken(token)
}

function readOptionValue(tokens, index) {
  const value = tokens[index + 1]

  if (isMissingOptionArgument(value)) {
    return {
      ok: false,
      message: 'expected one argument',
    }
  }

  return {
    ok: true,
    value,
    nextIndex: index + 1,
  }
}

function parseRequiredInt(optionName, rawValue) {
  const parsedValue = parsePythonInt(rawValue)

  if (!parsedValue.ok) {
    return {
      ok: false,
      message: `argument ${optionName}: ${parsedValue.message}`,
    }
  }

  return {
    ok: true,
    value: parsedValue.value,
  }
}

export function parseCommandLine(argv = []) {
  const tokens = Array.from(argv.slice(2), String)
  const programName = getProgramName(argv[1])

  if (tokens.includes('-h') || tokens.includes('--help')) {
    return {
      kind: 'help',
      code: 0,
      text: buildHelp(programName),
    }
  }

  let aValue
  let bValue
  let hasA = false
  let hasB = false
  const extras = []

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index]
    let optionName = null
    let rawValue = null

    if (token.startsWith('--a=')) {
      optionName = '--a'
      rawValue = token.slice(4)
    } else if (token.startsWith('--b=')) {
      optionName = '--b'
      rawValue = token.slice(4)
    } else if (token === '--a' || token === '--b') {
      const readResult = readOptionValue(tokens, index)

      if (!readResult.ok) {
        return {
          kind: 'error',
          code: 2,
          text: buildParserError(programName, `argument ${token}: ${readResult.message}`),
        }
      }

      optionName = token
      rawValue = readResult.value
      index = readResult.nextIndex
    } else {
      extras.push(token)
      continue
    }

    const parsedValue = parseRequiredInt(optionName, rawValue)

    if (!parsedValue.ok) {
      return {
        kind: 'error',
        code: 2,
        text: buildParserError(programName, parsedValue.message),
      }
    }

    if (optionName === '--a') {
      aValue = parsedValue.value
      hasA = true
    } else {
      bValue = parsedValue.value
      hasB = true
    }
  }

  const missingOptions = []

  if (!hasA) {
    missingOptions.push('--a')
  }

  if (!hasB) {
    missingOptions.push('--b')
  }

  if (missingOptions.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: buildParserError(
        programName,
        `the following arguments are required: ${missingOptions.join(', ')}`,
      ),
    }
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: buildParserError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    }
  }

  return {
    kind: 'ok',
    code: 0,
    values: {
      a: aValue,
      b: bValue,
    },
  }
}

import { parseCommandLine } from '../cli/argparse.mjs'
import { Int8ul, Struct, field } from '../construct/index.mjs'
import { PythonValueError, createBytes } from './bytes.mjs'
import { formatUnhandledValueError } from './pythonTraceback.mjs'

const structFormat = Struct(
  field('field1', Int8ul),
  field('field2', Int8ul),
)

function defaultEnvironment() {
  return {
    stdout: process.stdout,
    stderr: process.stderr,
    pid: process.pid,
  }
}

export function run(argv = process.argv, environment = defaultEnvironment()) {
  const parsedCommand = parseCommandLine(argv)

  if (parsedCommand.kind === 'help') {
    environment.stdout.write(`${parsedCommand.text}\n`)
    return 0
  }

  if (parsedCommand.kind === 'error') {
    environment.stderr.write(parsedCommand.text)
    return parsedCommand.code
  }

  try {
    const data = createBytes([parsedCommand.values.a, parsedCommand.values.b])
    const result = structFormat.parse(data)
    environment.stdout.write(`${result.toString()}\n`)
    return 0
  } catch (error) {
    if (error instanceof PythonValueError) {
      environment.stderr.write(formatUnhandledValueError(error, environment.pid))
      return 1
    }

    throw error
  }
}

export function main(argv = process.argv, environment = defaultEnvironment()) {
  const exitCode = run(argv, environment)
  process.exitCode = exitCode
  return exitCode
}
